import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-python-add-days-to-date":{"intro":"In Python, you can easily add or subtract days from a given date using the datetime module. This can be useful in various scenarios, such as calculating the due date of a task or project, or determining the date after a certain number of days from a given date.","steps":[{"title":"Add Days to Date","body":["Write a function add_days(n, d) that takes in two arguments:","• n: an integer representing the number of days to add (if positive) or subtract (if negative) from the given date. • d: an optional argument representing the date to which the days should be added or subtracted. If not provided, the current date should be used.","The function should return a datetime object representing the new date after adding or subtracting the specified number of days."],"code":[{"lang":"python","text":"from datetime import date\n\nadd_days(5, date(2020, 10, 25)) # returns datetime.date(2020, 10, 30)\nadd_days(-5, date(2020, 10, 25)) # returns datetime.date(2020, 10, 20)"}]}],"commands":[],"reference":[{"path":"add_days.py","text":"from datetime import datetime, timedelta\n\n\ndef add_days(n, d=datetime.today()):\n    return d + timedelta(n)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-check-if-list-elements-are-identical":{"intro":"In this challenge, you will implement a function to check if all elements in a list are identical, using the set() function and the len() function.","steps":[{"title":"Check if List Elements are Identical","body":["Check if List Elements are Identical","Write a function all_equal(lst) that takes a list as an argument and returns True if all elements in the list are identical, and False otherwise.","To solve this problem, you can use the following steps:","• Use set() to eliminate duplicate elements in the list. • Use len() to check if the length of the set is 1. • If the length of the set is 1, return True. Otherwise, return False."],"code":[{"lang":"python","text":"all_equal([1, 2, 3, 4, 5, 6]) # False\nall_equal([1, 1, 1, 1]) # True"}]}],"commands":[],"reference":[{"path":"all_equal.py","text":"def all_equal(lst):\n    return len(set(lst)) == 1"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-check-for-duplicates-in-list-function":{"intro":"In Python, a list is a collection of items that are ordered and changeable. Sometimes, we need to check if a list has any duplicate elements. In this challenge, you will write a Python function to check if a list has any duplicates.","steps":[{"title":"Check for Duplicates in List Function","body":["Check for Duplicates in List Function","Write a Python function called has_duplicates(lst) that takes a list as an argument and returns True if the list has any duplicate elements, otherwise returns False.","To solve this problem, you can follow these steps:","• Convert the list to a set to remove duplicates. • Compare the length of the set with the length of the original list. • If the lengths are equal, then the list has no duplicates, otherwise it has duplicates."],"code":[{"lang":"python","text":"has_duplicates([1, 2, 3, 4, 5]) # False\nhas_duplicates([1, 2, 3, 4, 5, 5]) # True\nhas_duplicates(['apple', 'banana', 'orange', 'banana']) # True\nhas_duplicates([]) # False"}]}],"commands":[],"reference":[{"path":"all_unique.py","text":"def all_unique(lst):\n    return len(lst) == len(set(lst))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-apply-predicate-based-function":{"intro":"In Python, functions are first-class objects, which means that they can be passed around like any other value. One useful application of this is to conditionally apply a function to a value based on some predicate. In this challenge, you will be asked to write a function that takes a predicate function and a function to apply when the predicate is true, and returns a new function that applies the function when the predicate is true.","steps":[{"title":"Apply Function When True","body":["Write a function called when that takes two arguments: a predicate function predicate and a function to apply when_true. The when function should return a new function that takes a single argument x. The new function should check if the value of predicate(x) is True. If it is, the new function should call when_true(x) and return the result. Otherwise, the new function should return x."],"code":[{"lang":"python","text":"def double(x):\n    return x * 2\n\ndef is_even(x):\n    return x % 2 == 0\n\ndouble_even_numbers = when(is_even, double)\ndouble_even_numbers(2) # 4\ndouble_even_numbers(1) # 1"}]}],"commands":[],"reference":[{"path":"when.py","text":"def when(predicate, when_true):\n    return lambda x: when_true(x) if predicate(x) else x"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-arithmetic-progression-generator":{"intro":"In this challenge, you will write a function that generates a list of numbers in an arithmetic progression starting with a given positive integer and up to a specified limit.","steps":[{"title":"Arithmetic Progression","body":["Write a function arithmetic_progression(n, lim) that takes in two positive integers n and lim and returns a list of numbers in the arithmetic progression starting with n and up to lim. The function should use range() and list() with the appropriate start, step, and end values to generate the list.","• Two positive integers n and lim where n is the starting number and lim is the limit.","• A list of numbers in the arithmetic progression starting with n and up to lim."],"code":[{"lang":"python","text":"arithmetic_progression(5, 25) # [5, 10, 15, 20, 25]"}]}],"commands":[],"reference":[{"path":"arithmetic_progression.py","text":"def arithmetic_progression(n, lim):\n    return list(range(n, lim + 1, n))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-calculate-average-in-python":{"intro":"In Python, calculating the average of a set of numbers is a common task. In this challenge, you will be asked to write a function that takes in two or more numbers and returns their average.","steps":[{"title":"Average Challenge","body":["Write a function called average that takes in two or more numbers and returns their average. Your function should follow these guidelines:","• Use sum() to sum all of the args provided, divide by len(). • The function should be able to handle any number of arguments. • The function should return a float."],"code":[{"lang":"python","text":"average(*[1, 2, 3]) # 2.0\naverage(1, 2, 3) # 2.0"}]}],"commands":[],"reference":[{"path":"average.py","text":"def average(*args):\n    return sum(args, 0.0) / len(args)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-mapped-list-average":{"intro":"In Python, we can use the map() function to apply a function to each element of a list and return a new list with the modified elements. We can also use the sum() function to add up all the elements of a list. In this challenge, we will combine these two functions to calculate the average of a list, after mapping each element to a value using a provided function.","steps":[{"title":"Mapped List Average","body":["Write a function called average_by(lst, fn = lambda x: x) that takes a list lst and a function fn as arguments. The function fn should be used to map each element of the list to a value. The function should then calculate the average of the mapped values and return it.","If the fn argument is not provided, the function should use the default identity function, which simply returns the element itself.","Your function should meet the following requirements:","• Use map() to map each element to the value returned by fn. • Use sum() to sum all of the mapped values, divide by len(lst). • Omit the last argument, fn, to use the default identity function."],"code":[{"lang":"python","text":"assert average_by([1, 2, 3, 4, 5]) == 3.0\nassert average_by([1, 2, 3, 4, 5], lambda x: x**2) == 11.0\nassert average_by([{ 'n': 4 }, { 'n': 2 }, { 'n': 8 }, { 'n': 6 }], lambda x: x['n']) == 5.0"}]}],"commands":[],"reference":[{"path":"average_by.py","text":"def average_by(lst, fn=lambda x: x):\n    return sum(map(fn, lst), 0.0) / len(lst)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-bifurcate-list-based-on-function":{"intro":"In this challenge, you will write a Python function that separates a list into two groups based on the result of a given filtering function, using a list comprehension.","steps":[{"title":"Bifurcate List Based on Function","body":["Bifurcate List Based on Function","Write a function bifurcate_by(lst, fn) that takes a list lst and a filtering function fn as arguments. The function should split the list into two groups based on the result of the filtering function. If the filtering function returns a truthy value for an element, it should be added to the first group. Otherwise, it should be added to the second group.","Your function should return a list of two lists, where the first list contains all the elements for which the filtering function returned a truthy value, and the second list contains all the elements for which the filtering function returned a falsy value.","Use a list comprehension to add elements to groups, based on the value returned by fn for each element."],"code":[{"lang":"python","text":"bifurcate_by(['beep', 'boop', 'foo', 'bar'], lambda x: x[0] == 'b')\n# [ ['beep', 'boop', 'bar'], ['foo'] ]"}]}],"commands":[],"reference":[{"path":"bifurcate_by.py","text":"def bifurcate_by(lst, fn):\n    return [[x for x in lst if fn(x)], [x for x in lst if not fn(x)]]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-byte-size-of-string":{"intro":"In Python, a string is a sequence of characters. Each character in a string takes up a certain amount of memory. The amount of memory taken up by a string is known as its byte size. In this challenge, you will write a function that takes a string as input and returns its byte size.","steps":[{"title":"Byte Size of String","body":["Write a function byte_size(s) that takes a string s as input and returns its byte size. The byte size of a string is the number of bytes required to store the string in memory. To calculate the byte size of a string, you need to encode the string using a specific encoding scheme. In this challenge, you will use the UTF-8 encoding scheme.","To calculate the byte size of a string, you can follow these steps:","• Encode the string using the UTF-8 encoding scheme. • Get the length of the encoded string.","Your function should return the length of the encoded string."],"code":[{"lang":"python","text":"byte_size('😀') # 4\nbyte_size('Hello World') # 11"}]}],"commands":[],"reference":[{"path":"byte_size.py","text":"def byte_size(s):\n    return len(s.encode(\"utf-8\"))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-camelcase-naming-convention-in-programming":{"intro":"Camelcase is a naming convention where a compound word or phrase is written in a way that the first word is in lowercase and the subsequent words are capitalized. This naming convention is commonly used in programming languages to name variables, functions, and classes.","steps":[{"title":"Camelcase String","body":["You are given a string that may contain spaces, hyphens, or underscores. Your task is to convert the string to camelcase by removing the spaces, hyphens, or underscores and capitalizing the first letter of each word except the first one. The first letter of the resulting string should be in lowercase."],"code":[{"lang":"python","text":"camel('some_database_field_name') # 'someDatabaseFieldName'\ncamel('Some label that needs to be camelized')\n# 'someLabelThatNeedsToBeCamelized'\ncamel('some-javascript-property') # 'someJavascriptProperty'\ncamel('some-mixed_string with spaces_underscores-and-hyphens')\n# 'someMixedStringWithSpacesUnderscoresAndHyphens'"}]}],"commands":[],"reference":[{"path":"camel.py","text":"from re import sub\n\n\ndef camel(s):\n    s = sub(r\"(_|-)+\", \" \", s).title().replace(\" \", \"\")\n    return \"\".join([s[0].lower(), s[1:]])"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-split-list-into-n-chunks":{"intro":"In this challenge, you will be asked to write a Python function that splits a given list into smaller lists of equal size, or with the remaining elements in the last list if the original list cannot be evenly divided.","steps":[{"title":"Split List into N Chunks","body":["Write a Python function called chunk_into_n(lst, n) that takes a list lst and an integer n as input and returns a list of n smaller lists, each containing an equal number of elements from the original list. If the original list cannot be split evenly into n smaller lists, the final chunk should contain the remaining elements.","To solve this problem, you can follow these steps:","• Calculate the size of each chunk by dividing the length of the original list by n and rounding up to the nearest integer using the math.ceil() function. • Create a new list of size n using the list() and range() functions. • Use the map() function to map each element of the new list to a chunk of the original list the length of size. • Return the list of smaller lists.","Your function should have the following signature:"],"code":[{"lang":"python","text":"def chunk_into_n(lst: list, n: int) -> list:"},{"lang":"python","text":"assert chunk_into_n([1, 2, 3, 4, 5, 6, 7], 4) == [[1, 2], [3, 4], [5, 6], [7]]\nassert chunk_into_n([1, 2, 3, 4, 5, 6, 7], 3) == [[1, 2, 3], [4, 5, 6], [7]]\nassert chunk_into_n([1, 2, 3, 4, 5, 6, 7], 2) == [[1, 2, 3, 4], [5, 6, 7]]\nassert chunk_into_n([1, 2, 3, 4, 5, 6, 7], 1) == [[1, 2, 3, 4, 5, 6, 7]]"}]}],"commands":[],"reference":[{"path":"chunk_into_n.py","text":"from math import ceil\n\n\ndef chunk_into_n(lst, n):\n    size = ceil(len(lst) / n)\n    return list(map(lambda x: lst[x * size : x * size + size], list(range(n))))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-clamping-numbers-within-range":{"intro":"In programming, it is often necessary to limit a number to a certain range. This is where the concept of clamping comes in. Clamping a number means restricting it to a certain range of values. In this challenge, you will be tasked with creating a function that clamps a number within a specified range.","steps":[{"title":"Clamp Number Challenge","body":["Write a function clamp_number(num, a, b) that takes in three parameters:","• num (integer or float): the number to be clamped • a (integer or float): the lower boundary of the range • b (integer or float): the upper boundary of the range","The function should clamp num within the inclusive range specified by the boundary values. If num falls within the range (a, b), return num. Otherwise, return the nearest number in the range."],"code":[{"lang":"python","text":"clamp_number(2, 3, 5) # 3\nclamp_number(1, -1, -5) # -1\nclamp_number(10, 1, 5) # 5\nclamp_number(-10, -5, -1) # -5"}]}],"commands":[],"reference":[{"path":"clamp_number.py","text":"def clamp_number(num, a, b):\n    return max(min(num, max(a, b)), min(a, b))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-invert-dictionary-with-non-unique-values":{"intro":"Dictionaries are a fundamental data structure in Python that allow you to store key-value pairs. Sometimes, you may need to invert a dictionary, which means swapping the keys and values so that the values become the keys and the keys become the values. In this challenge, you will be tasked with writing a function that inverts a dictionary with non-unique hashable values.","steps":[{"title":"Invert a Dictionary","body":["Write a function invert_dictionary(obj) that takes a dictionary obj as input and returns a new dictionary with the keys and values inverted. The input dictionary will have non-unique hashable values. If two or more keys have the same value, the function should append the keys to a list in the output dictionary.","To solve this problem, you can follow these steps:","• Create a collections.defaultdict with list as the default value for each key. • Use dictionary.items() in combination with a loop to map the values of the dictionary to keys using dict.append(). • Use dict() to convert the collections.defaultdict to a regular dictionary.","Function signature: def invert_dictionary(obj: dict) -> dict:"],"code":[{"lang":"python","text":"ages = {\n  'Peter': 10,\n  'Isabel': 10,\n  'Anna': 9,\n}\ninvert_dictionary(ages) # { 10: ['Peter', 'Isabel'], 9: ['Anna'] }"}]}],"commands":[],"reference":[{"path":"collect_dictionary.py","text":"from collections import defaultdict\n\n\ndef collect_dictionary(obj):\n    inv_obj = defaultdict(list)\n    for key, value in obj.items():\n        inv_obj[value].append(key)\n    return dict(inv_obj)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-combine-dictionary-values":{"intro":"Dictionaries are a fundamental data structure in Python, and they are used to store key-value pairs. Sometimes, we may need to combine the values of two or more dictionaries into a single dictionary. In this challenge, you will write a function that takes two or more dictionaries as arguments and returns a new dictionary that combines the values of the input dictionaries.","steps":[{"title":"Combine Dictionary Values","body":["Write a function combine_values(*dicts) that takes two or more dictionaries as arguments and returns a new dictionary that combines the values of the input dictionaries. The function should perform the following steps:","• Create a new collections.defaultdict with list as the default value for each key. • Loop over the input dictionaries and for each dictionary: • Loop over the keys of the dictionary. • Append the value of the key to the list of values for that key in the defaultdict. • Convert the defaultdict to a regular dictionary using the dict() function. • Return the resulting dictionary.","The function should have the following signature:"],"code":[{"lang":"python","text":"def combine_values(*dicts):\n    pass"},{"lang":"python","text":"d1 = {'a': 1, 'b': 'foo', 'c': 400}\nd2 = {'a': 3, 'b': 200, 'd': 400}\n\ncombine_values(d1, d2) # {'a': [1, 3], 'b': ['foo', 200], 'c': [400], 'd': [400]}"}]}],"commands":[],"reference":[{"path":"combine_values.py","text":"from collections import defaultdict\n\n\ndef combine_values(*dicts):\n    res = defaultdict(list)\n    for d in dicts:\n        for key in d:\n            res[key].append(d[key])\n    return dict(res)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-reverse-compose-functions":{"intro":"In this challenge, you will implement a function that performs left-to-right function composition using the reduce function from the functools module.","steps":[{"title":"Reverse Compose Functions","body":["Write a function compose_right that takes one or more functions as arguments and returns a new function that performs left-to-right function composition. The first (leftmost) function can accept one or more arguments; the remaining functions must be unary.","Your implementation should use the reduce function from the functools module to perform left-to-right function composition.","In the example above, we define two functions add and square. We then use the compose_right function to create a new function add_and_square that first adds two numbers and then squares the result. We then call the add_and_square function with the arguments 1 and 2, which returns 9."],"code":[{"lang":"python","text":"from functools import reduce\n\ndef compose_right(*fns):\n  # your code here"},{"lang":"python","text":"add = lambda x, y: x + y\nsquare = lambda x: x * x\nadd_and_square = compose_right(add, square)\nassert add_and_square(1, 2) == 9"}]}],"commands":[],"reference":[{"path":"compose_right.py","text":"from functools import reduce\n\n\ndef compose_right(*fns):\n    return reduce(lambda f, g: lambda *args: g(f(*args)), fns)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-count-grouped-elements":{"intro":"In Python, you can group elements of a list based on a given function. This can be useful when you want to count the number of occurrences of each group. In this challenge, you will be tasked with creating a function that groups the elements of a list based on a given function and returns the count of elements in each group.","steps":[{"title":"Count Grouped Elements","body":["Write a function count_by(lst, fn = lambda x: x) that takes a list lst and a function fn as arguments. The function should group the elements of the list based on the given function and return a dictionary with the count of elements in each group.","To solve this problem, you can follow these steps:","• Initialize a dictionary using collections.defaultdict. • Use map() to apply the given function to each element of the list. • Iterate over the mapped values and increase the count of each element in the dictionary.","The function should return the resulting dictionary."],"code":[{"lang":"python","text":"count_by([6.1, 4.2, 6.3], floor) # {6: 2, 4: 1}\ncount_by(['one', 'two', 'three'], len) # {3: 2, 5: 1}"}]}],"commands":[],"reference":[{"path":"count_by.py","text":"from collections import defaultdict\n\n\ndef count_by(lst, fn=lambda x: x):\n    count = defaultdict(int)\n    for val in map(fn, lst):\n        count[val] += 1\n    return dict(count)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-partial-sum-list":{"intro":"In mathematics, a partial sum is the sum of the first n terms of a series. In Python, we can create a list of partial sums using the itertools.accumulate() function. In this challenge, you will create a function that takes a list of numbers and returns a list of partial sums.","steps":[{"title":"Partial Sum List","body":["Write a function partial_sum(lst) that takes a list of numbers as an argument and returns a list of partial sums. Your function should perform the following steps:","• Use itertools.accumulate() to create the accumulated sum for each element in the list. • Use list() to convert the result into a list. • Return the list of partial sums."],"code":[{"lang":"python","text":"partial_sum([1, 2, 3, 4, 5]) # [1, 3, 6, 10, 15]\npartial_sum([2, 4, 6, 8, 10]) # [2, 6, 12, 20, 30]\npartial_sum([5, 10, 15, 20, 25]) # [5, 15, 30, 50, 75]"}]}],"commands":[],"reference":[{"path":"cumsum.py","text":"from itertools import accumulate\n\n\ndef cumsum(lst):\n    return list(accumulate(lst))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-generate-date-range-in-python":{"intro":"In this challenge, you will create a Python function that generates a list of dates between two given dates, demonstrating your understanding of the datetime module and list comprehension.","steps":[{"title":"Date Range Challenge","body":["Write a Python function called daterange(start, end) that takes two datetime.date objects as arguments and returns a list of all the dates between them. The list should include the start date but not the end date.","To solve this problem, you can follow these steps:","• Use datetime.timedelta.days to get the number of days between start and end. • Use int() to convert the result to an integer and range() to iterate over each day. • Use a list comprehension and datetime.timedelta to create a list of datetime.date objects."],"code":[{"lang":"python","text":"from datetime import date\n\ndaterange(date(2020, 10, 1), date(2020, 10, 5))\n# [date(2020, 10, 1), date(2020, 10, 2), date(2020, 10, 3), date(2020, 10, 4)]"}]}],"commands":[],"reference":[{"path":"daterange.py","text":"from datetime import timedelta, date\n\n\ndef daterange(start, end):\n    return [start + timedelta(n) for n in range(int((end - start).days))]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-date-difference-in-days":{"intro":"In Python, we can calculate the difference between two dates in days using the datetime module. This challenge will test your ability to write a function that takes two dates as input and returns the number of days between them.","steps":[{"title":"Date Difference in Days","body":["Write a function days_diff(start, end) that takes two date objects as input and returns the number of days between them. The function should subtract start from end and use datetime.timedelta.days to get the day difference."],"code":[{"lang":"python","text":"from datetime import date\n\nassert days_diff(date(2020, 10, 25), date(2020, 10, 28)) == 3\nassert days_diff(date(2021, 1, 1), date(2021, 1, 1)) == 0\nassert days_diff(date(2021, 1, 1), date(2021, 1, 2)) == 1"}]}],"commands":[],"reference":[{"path":"days_diff.py","text":"def days_diff(start, end):\n    return (end - start).days"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-days-from-now":{"intro":"In this challenge, you will learn how to use the datetime module in Python to calculate the date of n days from the current date.","steps":[{"title":"Days from now","body":["Write a function days_from_now(n) that takes an integer n as input and returns the date of n days from today.","To solve this problem, you can follow these steps:","• Import the datetime module. • Use the date.today() method to get the current date. • Use the timedelta method to add n days to the current date. • Return the new date."],"code":[{"lang":"python","text":">>> days_from_now(5)\ndatetime.date(2022, 12, 28)\n>>> days_from_now(10)\ndatetime.date(2022, 1, 2)"}]}],"commands":[],"reference":[{"path":"days_from_now.py","text":"from datetime import timedelta, date\n\n\ndef days_from_now(n):\n    return date.today() + timedelta(n)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-degrees-to-radians":{"intro":"In this challenge, you will be asked to write a function that converts an angle from degrees to radians using the formula radians = (degrees * pi) / 180.0, where pi is the ratio of a circle's circumference to its diameter.","steps":[{"title":"Degrees to Radians Challenge","body":["Write a function degrees_to_rads(deg) that takes an angle in degrees as an argument and returns the angle in radians. Your function should use the following formula to convert degrees to radians:","where pi is a constant value representing the ratio of the circumference of a circle to its diameter (approximately 3.14159).","Your function should return the angle in radians rounded to 4 decimal places."],"code":[{"lang":"text","text":"radians = (degrees * pi) / 180.0"},{"lang":"python","text":"degrees_to_rads(180) # returns 3.1416\ndegrees_to_rads(90) # returns 1.5708\ndegrees_to_rads(45) # returns 0.7854"}]}],"commands":[],"reference":[{"path":"degrees_to_rads.py","text":"from math import pi\n\n\ndef degrees_to_rads(deg):\n    return (deg * pi) / 180.0"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-delayed-function-execution":{"intro":"In Python, sometimes we need to delay the execution of a function for a certain amount of time. This can be useful in scenarios where we want to wait for a certain event to occur before executing a function. In this challenge, you will be asked to create a function that delays the execution of another function by a specified amount of time.","steps":[{"title":"Delayed Function Execution","body":["Write a function delay(fn, ms, *args) that takes a function fn, a time in milliseconds ms, and any number of arguments args. The function should delay the execution of fn by ms milliseconds and then invoke it with the provided arguments. The function should return the result of invoking fn.","To delay the execution of fn, use the time.sleep() function. This function takes a number of seconds as an argument, so you will need to convert ms to seconds before passing it to time.sleep().","In the example above, the add function is delayed by 2000 milliseconds (2 seconds) before being invoked with the arguments 2 and 3. The result of the add function is then returned and printed to the console."],"code":[{"lang":"python","text":"def add(x, y):\n  return x + y\n\nresult = delay(add, 2000, 2, 3)\nprint(result) # Output: 5"}]}],"commands":[],"reference":[{"path":"delay.py","text":"from time import sleep\n\n\ndef delay(fn, ms, *args):\n    sleep(ms / 1000)\n    return fn(*args)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-python-list-difference-calculation":{"intro":"In Python, we can calculate the difference between two lists or any iterable objects. The difference between two lists is the elements that are present in the first list but not in the second list. In this challenge, you will be required to write a Python function that takes two lists as arguments and returns the difference between them.","steps":[{"title":"List Difference","body":["Write a Python function called list_difference(a, b) that takes two lists as arguments and returns the difference between them. The function should not filter out duplicate values. To solve this problem, you can follow these steps:","• Create a set from the second list b. • Use a list comprehension on the first list a to only keep values not contained in the previously created set _b. • Return the resulting list."],"code":[{"lang":"python","text":"list_difference([1, 2, 3], [1, 2, 4]) # [3]"}]}],"commands":[],"reference":[{"path":"difference.py","text":"def difference(a, b):\n    _b = set(b)\n    return [item for item in a if item not in _b]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-list-difference-based-on-function":{"intro":"In Python, we can easily find the difference between two lists using the built-in set() function. However, what if we want to find the difference based on a specific function applied to each element in both lists? In this challenge, you will create a function that takes in two lists and a function, and returns the difference between the two lists after applying the provided function to each list element of both.","steps":[{"title":"List Difference Based on Function","body":["List Difference Based on Function","Create a function called difference_by(a, b, fn) that takes in three parameters:","• a: a list of elements • b: a list of elements • fn: a function that will be applied to each element in both lists","The function should return a list of elements that are in list a but not in list b, after applying the provided function fn to each element in both lists."],"code":[{"lang":"python","text":"difference_by([2.1, 1.2], [2.3, 3.4], floor) # [1.2]\ndifference_by([{ 'x': 2 }, { 'x': 1 }], [{ 'x': 1 }], lambda v : v['x'])\n# [ { x: 2 } ]"}]}],"commands":[],"reference":[{"path":"difference_by.py","text":"def difference_by(a, b, fn):\n    _b = set(map(fn, b))\n    return [item for item in a if fn(item) not in _b]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-convert-number-to-digit-list-in-python":{"intro":"In Python, it is often necessary to convert a number into a list of its digits. This can be useful for various applications, such as performing mathematical operations on individual digits or manipulating numbers in a more granular way. In this challenge, you will be tasked with writing a function that takes a number as input and returns a list of its digits.","steps":[{"title":"Digitize Number","body":["Write a function digitize(n) that takes a non-negative integer n as input and returns a list of its digits. The function should accomplish this by performing the following steps:","• Convert the input number n to a string. • Use the map() function combined with the int function to convert each character in the string to an integer. • Return the resulting list of integers.","For example, if the input number is 123, the function should return the list [1, 2, 3]."],"code":[{"lang":"python","text":"assert digitize(123) == [1, 2, 3]\nassert digitize(4567) == [4, 5, 6, 7]\nassert digitize(0) == [0]"}]}],"commands":[],"reference":[{"path":"digitize.py","text":"def digitize(n):\n    return list(map(int, str(n)))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-every-nth-element-in-list":{"intro":"In Python, we can access elements in a list using their index. Sometimes we may want to extract every nth element from a list. In this challenge, you are tasked with writing a function that takes a list and an integer nth as arguments and returns a new list containing every nth element of the original list.","steps":[{"title":"Every nth element in list","body":["Write a function every_nth(lst, nth) that takes a list lst and an integer nth as arguments and returns a new list containing every nth element of the original list.","• The input list lst will contain at least nth elements. • The value of nth will be greater than 0."],"code":[{"lang":"python","text":"every_nth([1, 2, 3, 4, 5, 6], 2) # [ 2, 4, 6 ]"}]}],"commands":[],"reference":[{"path":"every_nth.py","text":"def every_nth(lst, nth):\n    return lst[nth - 1 :: nth]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-fibonacci-sequence-generator":{"intro":"The Fibonacci sequence is a series of numbers in which each number is the sum of the two preceding ones. It starts with 0 and 1, and the next number is the sum of the previous two numbers. In this challenge, you will write a function that generates a list containing the Fibonacci sequence up until the nth term.","steps":[{"title":"Fibonacci Challenge","body":["Write a function called fibonacci(n) that takes an integer n as its parameter and returns a list containing the Fibonacci sequence up until the nth term.","To solve this problem, you can follow these steps:","• Create an empty list called sequence. • If n is less than or equal to 0, append 0 to the sequence list and return the list. • Append 0 and 1 to the sequence list. • Use a while loop to add the sum of the last two numbers of the sequence list to the end of the list, until the length of the list reaches n. • Return the sequence list."],"code":[{"lang":"python","text":"fibonacci(7) # [0, 1, 1, 2, 3, 5, 8, 13]"}]}],"commands":[],"reference":[{"path":"fibonacci.py","text":"def fibonacci(n):\n    if n <= 0:\n        return [0]\n    sequence = [0, 1]\n    while len(sequence) <= n:\n        next_value = sequence[len(sequence) - 1] + sequence[len(sequence) - 2]\n        sequence.append(next_value)\n    return sequence"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-filter-non-unique-list-values":{"intro":"In Python, a list is a collection of items that can be of different data types. Sometimes, we need to filter out the non-unique values from a list. In this challenge, you will create a function that takes a list as an argument and returns a new list with only the unique values.","steps":[{"title":"Filter Non-Unique List Values","body":["Write a Python function called filter_non_unique(lst) that takes a list as an argument and returns a new list with only the unique values. To solve this problem, you can follow these steps:","• Use the collections.Counter method to get the count of each value in the list. • Use a list comprehension to create a list containing only the unique values."],"code":[{"lang":"python","text":"filter_non_unique([1, 2, 2, 3, 4, 4, 5]) # [1, 3, 5]\nfilter_non_unique(['apple', 'banana', 'apple', 'orange', 'pear', 'banana']) # ['orange', 'pear']"}]}],"commands":[],"reference":[{"path":"filter_non_unique.py","text":"from collections import Counter\n\n\ndef filter_non_unique(lst):\n    return [item for item, count in Counter(lst).items() if count == 1]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-filter-unique-list-values":{"intro":"In this challenge, you will write a Python function that takes a list as input and returns a new list containing only the non-unique values from the original list.","steps":[{"title":"Filter Unique List Values","body":["Write a Python function called filter_unique(lst) that takes a list as an argument and returns a new list with only the non-unique values. To solve this problem, you can follow these steps:","• Use collections.Counter to get the count of each value in the list. • Use a list comprehension to create a list containing only the non-unique values.","Your function should satisfy the following requirements:","• The function should take a list as an argument. • The function should return a new list with only the non-unique values. • The function should not modify the original list. • The function should be case-sensitive, meaning that 'a' and 'A' are considered different values."],"code":[{"lang":"python","text":"def filter_unique(lst):\n    # your code here"},{"lang":"python","text":"assert filter_unique([1, 2, 2, 3, 4, 4, 5]) == [2, 4]\nassert filter_unique(['a', 'b', 'c', 'b', 'd', 'e', 'e']) == ['b', 'e']"}]}],"commands":[],"reference":[{"path":"filter_unique.py","text":"from collections import Counter\n\n\ndef filter_unique(lst):\n    return [item for item, count in Counter(lst).items() if count > 1]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-find-all-matching-indexes":{"intro":"In Python, we can use the enumerate() function to iterate over a list and get both the index and the value of each element. We can also use list comprehension to filter elements that satisfy a certain condition. In this challenge, you will use these concepts to create a function that finds the indexes of all elements in a list that satisfy a given testing function.","steps":[{"title":"Find All Matching Indexes","body":["Write a function find_index_of_all(lst, fn) that takes a list lst and a testing function fn as arguments and returns a list of indexes of all elements in lst for which fn returns True.","• A list lst of integers. • A testing function fn that takes an integer as input and returns a boolean value.","• A list of integers representing the indexes of all elements in lst for which fn returns True.","• In the first example, the testing function lambda n: n % 2 == 1 checks if the integer is odd. The function returns [0, 2] because the elements at indexes 0 and 2 of the list [1, 2, 3, 4] are odd. • In the second example, the testing function lambda n: n > 2 checks if the integer is greater than 2. The function returns [2, 3] because the elements at indexes 2 and 3 of the list [1, 2, 3, 4] are greater than 2. • In the third example, the testing function lambda n: n < 0 checks if the integer is negative. The function returns [] because there are no negative elements in the list [1, 2, 3, 4]."],"code":[{"lang":"python","text":"find_index_of_all([1, 2, 3, 4], lambda n: n % 2 == 1) # [0, 2]\nfind_index_of_all([1, 2, 3, 4], lambda n: n > 2) # [2, 3]\nfind_index_of_all([1, 2, 3, 4], lambda n: n < 0) # []"}]}],"commands":[],"reference":[{"path":"find_index_of_all.py","text":"def find_index_of_all(lst, fn):\n    return [i for i, x in enumerate(lst) if fn(x)]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-find-key-by-value-in-python-dictionary":{"intro":"In this challenge, you will write a function that finds the first key in a dictionary that has a given value.","steps":[{"title":"Find the Key of a Value in a Dictionary","body":["Find the Key of a Value in a Dictionary","Write a function find_key(dict, val) that finds the first key in the provided dictionary that has the given value.","• Take a dictionary dict and a value val as input. • Use dictionary.items() and next() to return the first key that has a value equal to val. • Return the key as output."],"code":[{"lang":"python","text":"ages = {\n  'Peter': 10,\n  'Isabel': 11,\n  'Anna': 9,\n}\nfind_key(ages, 11) # 'Isabel'"}]}],"commands":[],"reference":[{"path":"find_key.py","text":"def find_key(dict, val):\n    return next(key for key, value in dict.items() if value == val)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-find-parity-outliers":{"intro":"In this challenge, you are required to write a function that identifies the parity outliers (elements with a different parity than the majority) in a given list of integers.","steps":[{"title":"Find Parity Outliers","body":["Write a function find_parity_outliers(nums) that takes a list of integers nums as an argument and returns a list of all the parity outliers in nums.","To solve this problem, you can follow these steps:","• Use collections.Counter with a list comprehension to count even and odd values in the list. • Use collections.Counter.most_common() to get the most common parity. • Use a list comprehension to find all elements that do not match the most common parity.","In the example above, the majority of the elements in the list are even, so the parity outliers are the odd elements 1 and 3."],"code":[{"lang":"python","text":"find_parity_outliers([1, 2, 3, 4, 6]) # [1, 3]"}]}],"commands":[],"reference":[{"path":"find_parity_outliers.py","text":"from collections import Counter\n\n\ndef find_parity_outliers(nums):\n    return [\n        x for x in nums if x % 2 != Counter([n % 2 for n in nums]).most_common()[0][0]\n    ]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-execute-function-for-each-list-element":{"intro":"In this challenge, you will create a function that takes a list and a function as arguments, and executes the function for each element in the list.","steps":[{"title":"Execute Function for Each List Element","body":["Execute Function for Each List Element","Write a function for_each(itr, fn) that takes a list itr and a function fn as arguments. The function should execute fn once for each element in itr.","In the example above, the for_each function is called with a list [1, 2, 3] and a function print_square. The print_square function is executed once for each element in the list, printing the square of each number."],"code":[{"lang":"python","text":"def print_square(num):\n    print(num*num)\n\nfor_each([1, 2, 3], print_square) # prints 1 4 9"}]}],"commands":[],"reference":[{"path":"for_each.py","text":"def for_each(itr, fn):\n    for el in itr:\n        fn(el)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-reverse-iteration-in-python":{"intro":"In this challenge, you will need to implement a function that executes a given function for each element in a list, starting from the last element and working backwards.","steps":[{"title":"Execute function for each list element in reverse","body":["Execute function for each list element in reverse","Write a function for_each_right(itr, fn) that takes a list itr and a function fn as arguments. The function should execute fn once for each element in itr, starting from the last one.","• The function should work for any list and function. • The function should not modify the original list."],"code":[{"lang":"python","text":"for_each_right([1, 2, 3], print) # 3 2 1"}]}],"commands":[],"reference":[{"path":"for_each_right.py","text":"def for_each_right(itr, fn):\n    for el in itr[::-1]:\n        fn(el)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-create-frequency-dictionary-from-list":{"intro":"In this challenge, you will create a Python function that takes a list as an argument and returns a dictionary with the unique values of the list as keys and their frequencies as the values. This is a common task in data analysis and can be useful in many different applications.","steps":[{"title":"Value Frequencies","body":["Write a Python function called value_frequencies(lst) that takes a list as an argument and returns a dictionary with the unique values of the list as keys and their frequencies as the values.","To solve this problem, you can follow these steps:","• Create an empty dictionary to store the frequencies of each unique element. • Loop through the list and use collections.defaultdict to store the frequencies of each unique element. • Use dict() to return a dictionary with the unique elements of the list as keys and their frequencies as the values.","Your function should return the dictionary with the unique values and their frequencies."],"code":[{"lang":"python","text":"value_frequencies(['a', 'b', 'a', 'c', 'a', 'a', 'b']) # { 'a': 4, 'b': 2, 'c': 1 }"}]}],"commands":[],"reference":[{"path":"frequencies.py","text":"from collections import defaultdict\n\n\ndef frequencies(lst):\n    freq = defaultdict(int)\n    for val in lst:\n        freq[val] += 1\n    return dict(freq)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-convert-iso-date":{"intro":"In Python, dates can be represented in various formats. One such format is the ISO-8601 format, which is a standard format for representing dates and times. In this challenge, you will be tasked with converting a date from its ISO-8601 representation to a datetime.datetime object.","steps":[{"title":"Convert ISO Date","body":["Write a function from_iso_date(d) that takes a string d representing a date in ISO-8601 format and returns a datetime.datetime object representing the same date and time."],"code":[{"lang":"python","text":"from_iso_date('2020-10-28T12:30:59.000000') # returns datetime.datetime(2020, 10, 28, 12, 30, 59)"}]}],"commands":[],"reference":[{"path":"from_iso_date.py","text":"from datetime import datetime\n\n\ndef from_iso_date(d):\n    return datetime.fromisoformat(d)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-geometric-progression-sequence-generator":{"intro":"In mathematics, a geometric progression is a sequence of numbers in which each term after the first is found by multiplying the previous one by a fixed, non-zero number called the common ratio. In this challenge, you will create a function that initializes a list containing the numbers in the specified range where start and end are inclusive and the ratio between two terms is step.","steps":[{"title":"Geometric Progression Challenge","body":["Geometric Progression Challenge","Write a function called geometric_progression that takes in three parameters:","• end: an integer representing the end of the range (inclusive) • start: an optional integer representing the start of the range (inclusive), with a default value of 1 • step: an optional integer representing the common ratio between two terms, with a default value of 2","The function should return a list containing the numbers in the specified range where the ratio between two terms is step. The list should start with start and end with end."],"code":[{"lang":"python","text":"geometric_progression(256) # [1, 2, 4, 8, 16, 32, 64, 128, 256]\ngeometric_progression(256, 3) # [3, 6, 12, 24, 48, 96, 192]\ngeometric_progression(256, 1, 4) # [1, 4, 16, 64, 256]"}]}],"commands":[],"reference":[{"path":"geometric_progression.py","text":"from math import floor, log\n\n\ndef geometric_progression(end, start=1, step=2):\n    return [start * step**i for i in range(floor(log(end / start) / log(step)) + 1)]"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-group-list-elements":{"intro":"In this challenge, you will be asked to write a function that groups the elements of a list based on the result of applying a given function to each element.","steps":[{"title":"Group List Elements","body":["Write a function group_by(lst, fn) that takes a list lst and a function fn as arguments and returns a dictionary where the keys are the results of applying fn to the elements of lst and the values are lists of elements from lst that produce the corresponding key when fn is applied to them.","For example, if we have a list of numbers [6.1, 4.2, 6.3] and we want to group them by their integer part, we can use the floor function from the math module as the grouping function. The expected output would be {4: [4.2], 6: [6.1, 6.3]}."],"code":[{"lang":"python","text":"from math import floor\n\ngroup_by([6.1, 4.2, 6.3], floor) # {4: [4.2], 6: [6.1, 6.3]}\ngroup_by(['one', 'two', 'three'], len) # {3: ['one', 'two'], 5: ['three']}"}]}],"commands":[],"reference":[{"path":"group_by.py","text":"from collections import defaultdict\n\n\ndef group_by(lst, fn):\n    d = defaultdict(list)\n    for el in lst:\n        d[fn(el)].append(el)\n    return dict(d)"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-hamming-distance-calculation-challenge":{"intro":"The Hamming distance is a measure of the difference between two strings of equal length. In other words, it is the number of positions at which the corresponding symbols are different. In this challenge, you will be asked to write a function that calculates the Hamming distance between two values.","steps":[{"title":"Hamming Distance Challenge","body":["Write a function hamming_distance(a, b) that takes two integers as arguments and returns the Hamming distance between them. The function should perform the following steps:","• Use the XOR operator (^) to find the bit difference between the two numbers. • Use bin() to convert the result to a binary string. • Convert the string to a list and use count() of str class to count and return the number of 1s in it."],"code":[{"lang":"python","text":"hamming_distance(2, 3) # 1\nhamming_distance(10, 4) # 2\nhamming_distance(0, 255) # 8"}]}],"commands":[],"reference":[{"path":"hamming_distance.py","text":"def hamming_distance(a, b):\n    return bin(a ^ b).count(\"1\")"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"},"labex-python-check-for-duplicates-in-a-list":{"intro":"In this challenge, you will write a Python function to check if a list contains any duplicate values.","steps":[{"title":"Check for Duplicates in a List","body":["Check for Duplicates in a List","Write a Python function called has_duplicates(lst) that takes a list as an argument and returns True if the list contains any duplicates, and False otherwise.","To solve this problem, you can use the following steps:","• Use the set() function to remove duplicates from the list. • Compare the length of the original list with the length of the set. If they are the same, then there are no duplicates. If they are different, then there are duplicates."],"code":[{"lang":"python","text":"x = [1, 2, 3, 4, 5, 5]\ny = [1, 2, 3, 4, 5]\nprint(has_duplicates(x)) # True\nprint(has_duplicates(y)) # False"}]}],"commands":[],"reference":[{"path":"has_duplicates.py","text":"def has_duplicates(lst):\n    return len(lst) != len(set(lst))"}],"source":"30-seconds/30-seconds-of-python · by huduo0812, jiaosenvip · CC-BY-4.0"}};
